// William Gannon && Todd Sewright// CS 162 Dr. Shirey Tu/Th 2pm-4pm// <wgannnon@mindspring.com>public class Bank{	private static Account[] active_accounts;	private int accounts_held, available_accounts, this_one;	private static String report = new String("");		public Bank(){		available_accounts = 30;		active_accounts = new Account[available_accounts];		accounts_held = 0;	} // Constructor Bank	public Account getAccountInfo(String target_account){		int index = 0;			while (index < accounts_held){			if ((active_accounts[index].getAccountNumber()				).compareTo(target_account) == 0){								//active_accounts[index].print();				return active_accounts[index];			}			else 				index++;		}		return null;	} // method getAccountInfo		public void removeAccount(String target_account){		for (int index = 0; index < accounts_held; index++){			if ((active_accounts[index].getAccountNumber()				).compareTo(target_account) == 0){				   accounts_held--;				for(int count=index; count<accounts_held;					count++){					active_accounts[count] = active_accounts						[count+1];					active_accounts[count+1] = null;				}			}		}	}// method removeAccount	public void addAccount(){		if(accounts_held == available_accounts)			increaseBankSize();		active_accounts[accounts_held] = new Account();		accounts_held++; 	}// method addAccount	public void addAccount(String given_name, String sir_name, 		String acct_number, String ph_number, double initial_balance)	{		if(accounts_held == available_accounts)			increaseBankSize();		active_accounts[accounts_held] = new Account(given_name, 			sir_name, acct_number, ph_number, initial_balance);		accounts_held++; 	}// method AddAccount	public void interest(){		System.out.println("** 3% Shirey Bonus **");		for(int index = 0; index < accounts_held; index++){			active_accounts[index].interest();		}	} // method interest	private void increaseBankSize(){		int increase_me = available_accounts + 10;		available_accounts = increase_me;		Account[] accounts_temp = new Account[increase_me];		for(int customer = 0; customer < accounts_held; customer++)			accounts_temp[customer] = active_accounts[customer];				active_accounts = accounts_temp;			}// method increaseBankSize	private void increaseBankSize(int increaseBy){		int increase_me = available_accounts + increaseBy;		available_accounts = increase_me;		Account[] accounts_temp = new Account[increase_me];		for(int customer = 0; customer < available_accounts; customer++)			accounts_temp[customer] = active_accounts[customer];				active_accounts = accounts_temp;			}// method increaseBankSize	public void sortByName(){		Account[] accounts_temp = active_accounts;		for(int index = 1; index < accounts_held; index++){					Account key = accounts_temp[index];			int position = index;						while(position > 0 				&& accounts_temp[position-1].compareTo(key)> 0){							accounts_temp[position] 					= accounts_temp[position-1];				position--;						}			accounts_temp[position] = key;		}		active_accounts = accounts_temp;	}// method sortByName	public void sortByAccountNumber(){		Account[] accounts_temp = active_accounts;		for(int index = 1; index < accounts_held; index++){					Account key = accounts_temp[index];			int position = index;						while(position > 0 				&& (accounts_temp[position-1].getAccountNumber()					).compareTo(key.getAccountNumber())> 0){							accounts_temp[position] 					= accounts_temp[position-1];				position--;						}			accounts_temp[position] = key;		}		active_accounts = accounts_temp;	}// method sortByAccountNumber		public Account[] getAccounts(){		return active_accounts;	}		public String accountNumber(){		this_one = 0;		return active_accounts[this_one].getAccountNumber();			}	public String nextAccountNumber(){		this_one++;		return active_accounts[this_one].getAccountNumber();	}		public String toString(){		try{		for(int account_holder=0; account_holder < accounts_held; 				account_holder++){							report = active_accounts[account_holder].toString();		}}		catch(NullPointerException exception){					report = "** No Accounts Currently Available.**";		}		return report;			}//method print	public void print(){		for(int account_holder=0; account_holder < accounts_held;				 account_holder++){				active_accounts[account_holder].print();		}	}//method print} // class Bank